    DateTime.Now > a.ExpiresAt          // evaluated locally by accident
    || string.Format("{0}", a.Id) == x  // not translatable
    || a.Score switch { > 90 => true, _ => false }); // switch may not translate

// Safe pattern: pull first, then filter with full C#
var safe = attempts.Where(a => a.Tenant == tenant).ToList()
    .Where(a => DateTime.Now > a.ExpiresAt);

var snapshot = attempts.Where(a => a.Tenant == tenant).ToList();

// Only after profiling shows CPU-bound work on large in-memory snapshot:
var summary = snapshot.AsParallel()
    .Where(a => a.Score >= 50)
    .GroupBy(a => a.QuestionId)
    .Select(g => (g.Key, g.Count()))
    .ToList();

